#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int is_prime(long long n) {
    if (n < 2) return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (long long i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    return 1;
}
int is_circ(long long n) {
    char s[50], rot[50]; sprintf(s, "%lld", n);
    int len = strlen(s);
    for (int i = 0; i < len; i++) {
        int idx = 0;
        for (int j = i; j < len; j++) rot[idx++] = s[j];
        for (int j = 0; j < i; j++) rot[idx++] = s[j];
        rot[idx] = '\0';
        if (!is_prime(atoll(rot))) return 0;
    }
    return 1;
}
int main() {
    long long l, r; if (scanf("%lld %lld", &l, &r) != 2) return 0;
    int first = 1;
    for (long long x = l; x <= r; x++) {
        if (is_circ(x)) {
            if (!first) putchar(' ');
            printf("%lld", x); first = 0;
        }
    }
    putchar('\n');
    return 0;
}

